(() => {
  window.sleep = (ms) => new Promise((r) => setTimeout(r, ms))
  window.until = async (f, ms = 15000) => {
    const t0 = Date.now()
    while (Date.now() - t0 < ms) {
      if (f()) return true
      await sleep(150)
    }
    return false
  }
  window.nav = (name) =>
    [...document.querySelectorAll('nav button')].find((b) => b.textContent.trim() === name).click()
  window.chooseSelect = async (title, value) => {
    const el = [...document.querySelectorAll('select')].find((x) => x.title === title)
    if (!el) return 'NO SELECT ' + title
    Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set.call(el, String(value))
    el.dispatchEvent(new Event('change', { bubbles: true }))
    await sleep(1200)
    return title + ' = ' + (el.selectedOptions[0]?.textContent ?? el.value)
  }
  window.setInput = (input, value) => {
    const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set
    set.call(input, value)
    input.dispatchEvent(new Event('input', { bubbles: true }))
    input.dispatchEvent(new Event('change', { bubbles: true }))
  }
  window.clickText = async (text) => {
    const b = [...document.querySelectorAll('button,[role=tab]')].find((x) => x.textContent.trim() === text)
    if (!b) return 'NO BUTTON ' + text
    b.click()
    await sleep(1500)
    return 'clicked ' + text
  }
  window.openPlayer = async (name) => {
    const input = document.querySelector('input[aria-label="Search players"]')
    setInput(input, name)
    await until(() => [...document.querySelectorAll('aside button')].some((x) => x.textContent.includes(name)))
    const b = [...document.querySelectorAll('aside button')].find((x) => x.textContent.includes(name))
    if (!b) return 'NOT LISTED ' + name
    b.click()
    await until(() => document.querySelector('h1')?.innerText.includes(name.split(' ').pop()))
    return 'opened ' + document.querySelector('h1')?.innerText.replace(/\n/g, ' ')
  }
  window.check = (label, got, want) =>
    (JSON.stringify(got) === JSON.stringify(want) ? 'PASS ' : 'FAIL ') +
    label +
    ' got ' +
    JSON.stringify(got) +
    ' want ' +
    JSON.stringify(want)
  window.boardHead = () =>
    [...document.querySelectorAll('thead tr:last-child th')].map((c) => c.textContent.replace(/[▼▲]/g, '').replace(/shrunk$/, '').replace(/S$/, '').trim())
  window.boardRow = (name) => {
    const r = [...document.querySelectorAll('tbody tr')].find((x) => x.querySelector('button,span')?.textContent.trim() === name || x.innerText.split('\n').some((t) => t.trim() === name))
    return r ? [...r.querySelectorAll('td')].map((c) => c.textContent.trim()) : null
  }
  window.cellOf = (name, id) => {
    const heads = [...document.querySelectorAll('thead tr:last-child th')]
    const i = heads.findIndex((h) => h.dataset.metricHead === id)
    const r = boardRow(name)
    if (!r) return 'NO ROW ' + name
    return i < 0 ? 'NO HEAD ' + id : r[i]
  }
  window.cat = async () => {
    window.catalogue ??= new Map((await window.api.stats.catalogue()).map((m) => [m.id, m]))
    return window.catalogue
  }
  window.levelOf = (m) => m?.stability?.reliability ?? 'none'
  // The marks inside `root`, against the catalogue's labels.
  window.marks = async (root) => {
    const c = await cat()
    const heads = [...root.querySelectorAll('[data-metric-head]')]
    const wrong = heads.filter((h) => h.querySelector('[data-stability]')?.dataset.stability !== levelOf(c.get(h.dataset.metricHead)))
    return { heads: heads.length, withMark: heads.filter((h) => h.querySelector('[data-stability]')).length, wrong: wrong.map((h) => h.dataset.metricHead) }
  }
  window.r2 = (x) => x.toFixed(2)
  window.n0 = (x) => Math.round(x).toLocaleString('en-US')
  // The first line a card should show for a metric, from the catalogue.
  window.firstLine = (m) =>
    m.stability?.yearToYear != null
      ? `Year to year ${r2(m.stability.yearToYear)} on ${n0(m.stability.pairs)} pairs`
      : `Not measured: ${m.stability?.reason}`
  window.cardLines = () => [...document.querySelectorAll('[data-testid=stability-lines]')].at(-1)?.innerText.split('\n') ?? null
  window.fmtPct = (v) => (v * 100).toFixed(1) + '%'
  // A toggle's text gains its check mark when on, so it is found by its ending.
  window.toggle = async (label) => {
    const b = [...document.querySelectorAll('button')].find((x) => x.textContent.trim().endsWith(label))
    if (!b) return 'NO TOGGLE ' + label
    b.click()
    await sleep(3500)
    return label + ' pressed ' + b.getAttribute('aria-pressed')
  }
  window.into = async (selector) => {
    const el = document.querySelector(selector)
    if (!el) return 'NOT FOUND ' + selector
    el.scrollIntoView({ block: 'center', inline: 'center' })
    await sleep(600)
    return 'in view ' + selector
  }
  return 'helpers ready'
})()

