(async () => {
      const scope = { seasons: [2026] }
      const shrunk = await window.api.stats.query({ entity: 'player', metrics: ['ts_pct', 'min'], scope, shrunk: true, sort: { metric: 'ts_pct', dir: 'desc' }, limit: 1000 })
      const raw = await window.api.stats.query({ entity: 'player', metrics: ['ts_pct', 'min'], scope, sort: { metric: 'ts_pct', dir: 'desc' }, limit: 1000 })
      // The first player below the qualifier in the shrunk order: a low-minute player.
      const k = shrunk.rows.findIndex((x) => !x.values.min.qualified)
      const p = shrunk.rows[k]
      window.lowMinute = p.name
      const rawRank = raw.rows.findIndex((x) => x.id === p.id) + 1
      const qualifiedRaw = raw.rows.filter((x) => x.values.ts_pct.qualified && x.values.min.qualified).length
      const row = boardRow(p.name)
      const toggle = [...document.querySelectorAll('button')].find((b) => b.textContent.trim().endsWith('Shrunk rates'))
      const qual = [...document.querySelectorAll('button')].find((b) => b.textContent.trim().endsWith('Qualified only'))
      return [
        check('SHRUNK on: the toggle is on and Qualified only off', [toggle?.getAttribute('aria-pressed'), qual?.getAttribute('aria-pressed')], ['true', 'false']),
        check('the TS% head is marked shrunk', !!document.querySelector('th[data-metric-head="ts_pct"] [data-shrunk]'), true),
        check(`${p.name} (${Math.round(p.values.min.raw)} minutes, below the qualifier) ranks ${k + 1}, as the engine`, row?.[0]?.startsWith(String(k + 1) + p.name), true),
        check('marked NQ', row?.[0]?.includes(p.name + 'NQ'), true),
        check('his shrunk TS% on the board = engine', cellOf(p.name, 'ts_pct'), fmtPct(p.values.ts_pct.value)),
        `raw TS% ${fmtPct(p.values.ts_pct.raw)} on ${p.values.ts_pct.sample} attempts; unshrunk he sorts ${rawRank} of ${raw.rows.length}, after the ${qualifiedRaw} qualified`,
        'cell hover: ' + JSON.stringify([...document.querySelectorAll('tbody tr')].find((x) => x.innerText.includes(p.name))?.querySelectorAll('td')[(() => { const h = [...document.querySelectorAll('thead tr:last-child th')]; return h.findIndex((x) => x.dataset.metricHead === 'ts_pct') })()]?.title)
      ].join('\n')
    })()

